#!/bin/bash
set -euo pipefail
source /workspace/.turbo-picard-env/env.sh
cd /workspace/turbo-picard
export PATH=/workspace/scratch/rival-tools/installed/usr/bin:$PATH
export LD_LIBRARY_PATH=/workspace/scratch/rival-tools/installed/usr/lib/x86_64-linux-gnu${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}
export TURBO_PICARD_THREADS=0
export TURBO_PICARD_REQUIRE_NATIVE=1
export BASE_SHA=a4aeaa83659c581b7e2b7d587ad51faf4d48bc06
export HEAD_SHA=a4aeaa83659c581b7e2b7d587ad51faf4d48bc06+patch-444751b8237a923b3bc666c8b2a1932916fc06d7c1bd76cfa877b61ac671c0c5
python3 tools/bench_bounded_markduplicates.py --candidate target/release/turbo-picard --baseline /workspace/scratch/rival-tools/turbo-baseline --picard /workspace/scratch/rival-tools/picard-controlled --samtools /workspace/scratch/rival-tools/installed/usr/bin/samtools --output-dir benchmarks/runs/2026-10-25-final-bounded --repeats 3
python3 tools/bench_native_duplicate_landscape.py --candidate target/release/turbo-picard --picard /workspace/scratch/rival-tools/picard-controlled --samtools /workspace/scratch/rival-tools/installed/usr/bin/samtools --fastdup /workspace/scratch/rival-tools/fastdup-libdeflate --tools fastdup samtools --candidate-source a4aeaa83659c581b7e2b7d587ad51faf4d48bc06+patch-444751b8237a923b3bc666c8b2a1932916fc06d7c1bd76cfa877b61ac671c0c5 --input paired-600k=benchmarks/runs/2026-10-25-final-bounded/paired-600k/input.bam --input gatk-na12878-mito=benchmarks/real-data/gatk-na12878-mito/input.bam --output-dir benchmarks/runs/2026-10-25-final-native-competitors --repeats 3
python3 tools/compare_real_data.py --input-bam benchmarks/real-data/gatk-na12878-mito/input.bam --reference-fasta fixtures/reference/chrM.fa --input-source-url https://github.com/broadinstitute/gatk/blob/e8c49f600b06c658e0fa9bf67256340ebb46bc48/src/test/resources/org/broadinstitute/hellbender/tools/mutect/mito/NA12878.bam --input-source-commit e8c49f600b06c658e0fa9bf67256340ebb46bc48 --scope-caveat 'Pinned mitochondrial fixture; codec regression check, not cohort evidence' --picard-command /workspace/scratch/rival-tools/picard-controlled --turbo-picard-command /workspace/turbo-picard/target/release/turbo-picard --output-dir benchmarks/runs/2026-10-25-final-gatk-na12878-mito --skip-build --commands AddOrReplaceReadGroups BuildBamIndex CleanSam CollectAlignmentSummaryMetrics CollectInsertSizeMetrics CollectQualityYieldMetrics MarkDuplicates RevertSam SamToFastq SortSam ValidateSamFile ViewSam
